import 'package:test/test.dart';
import 'package:typesense/src/multi_search.dart';
import 'package:typesense/typesense.dart';

import 'test_utils.dart';

void main() {
  late SearchClient searchClient;

  setUp(() {
    searchClient = SearchClient(ConfigurationFactory.withNearestNode());
  });

  group('SearchClient', () {
    test('has a config field', () {
      expect(searchClient.config, isA<Configuration>());
    });
    test('has a multiSearch getter', () {
      expect(searchClient.multiSearch, isA<MultiSearch>());
    });
    test('has a collection method', () {
      expect(searchClient.collection('companies'), isA<Collection>());
    });
  });

  group('SearchClient initialization', () {
    test('sets multiSearch.useTextContentType to true', () {
      expect(searchClient.multiSearch.useTextContentType, isTrue);
    });
    test(
        'sets configuration.sendApiKeyAsQueryParam true if api key is less than 2000 characters, false otherwise',
        () {
      var config = ConfigurationFactory.withNearestNode(
              apiKey: 'abc123', sendApiKeyAsQueryParam: false),
          multiSearch = SearchClient(config);
      expect(multiSearch.config.sendApiKeyAsQueryParam, isTrue);

      config = ConfigurationFactory.withNearestNode(
          apiKey: () {
            var key = 'abc123';
            while (key.length <= 2000) {
              key += key;
            }
            return key;
          }(),
          sendApiKeyAsQueryParam: true);
      multiSearch = SearchClient(config);
      expect(multiSearch.config.sendApiKeyAsQueryParam, isFalse);
    });
  });

  test(
      'SearchClient.collection returns the same document object for a particular documentId',
      () {
    final document = searchClient.collection('companies');
    expect(searchClient.collection('companies').hashCode,
        equals(document.hashCode));
  });
}

import 'package:test/test.dart';
import 'package:http/http.dart' as http;

import 'package:typesense/src/models/models.dart';
import 'package:typesense/src/exceptions/exceptions.dart'
    show MissingConfiguration;

const host = 'localhost';
const path = '/path/to/service';

void main() {
  group('Node', () {
    final n1 = Node(
      Protocol.http,
      host,
      port: 8080,
      path: path,
      client: http.Client(),
    );
    final n2 = Node.withUri(
      Uri(
        scheme: 'http',
        host: host,
        port: 8080,
        path: path,
      ),
      client: http.Client(),
    );

    test('has a protocol field', () {
      expect(n1.protocol, equals(Protocol.http));
      expect(n2.protocol, equals(Protocol.http));
    });
    test('has a host field', () {
      expect(n1.host, equals('localhost'));
      expect(n2.host, equals('localhost'));
    });
    test('has a port field', () {
      expect(n1.port, equals(8080));
      expect(n2.port, equals(8080));
    });
    test('has a path field', () {
      expect(n1.path, equals('/path/to/service'));
      expect(n2.path, equals('/path/to/service'));
    });
    test('has a uri field', () {
      expect(
          n1.uri.toString(), equals('http://localhost:8080/path/to/service'));
      expect(
          n2.uri.toString(), equals('http://localhost:8080/path/to/service'));
    });
    test('has a isHealthy field', () {
      expect(n1.isHealthy, isTrue);
      expect(n2.isHealthy, isTrue);
    });
    test('has a lastAccessTimestamp field', () {
      final dateTime = DateTime.now();
      n1.lastAccessTimestamp = dateTime;
      n2.lastAccessTimestamp = dateTime;

      expect(n1.lastAccessTimestamp, equals(dateTime));
      expect(n2.lastAccessTimestamp, equals(dateTime));
    });
    test('has a client field', () {
      expect(n1.client, isA<http.BaseClient>());
      expect(n2.client, isA<http.BaseClient>());
    });
    test('has a isDueForHealthCheck method', () async {
      final healthcheckInterval = Duration(seconds: 2);

      n1.lastAccessTimestamp = DateTime.now();
      await Future.delayed(Duration(seconds: 1, milliseconds: 100));
      expect(n1.isDueForHealthCheck(healthcheckInterval), isFalse);

      n1.lastAccessTimestamp = DateTime.now();
      await Future.delayed(Duration(seconds: 2, milliseconds: 100));
      expect(n1.isDueForHealthCheck(healthcheckInterval), isTrue);
    });
  });

  group('Node initialization', () {
    test('with missing port and http protocol, sets port to 80', () {
      final n1 = Node(Protocol.http, host, path: path);
      final n2 = Node.withUri(Uri(scheme: 'http', host: host, path: path));

      expect(n1.port, equals(80));
      expect(n2.port, equals(80));
    });
    test('with missing port and https protocol, sets port to 443', () {
      final n1 = Node(Protocol.https, 'localhost', path: '/path/to/service');
      final n2 = Node.withUri(Uri(scheme: 'https', host: host, path: path));

      expect(n1.port, equals(443));
      expect(n2.port, equals(443));
    });
    test('with missing path, sets path as empty String', () {
      final n1 = Node(Protocol.http, 'localhost', port: 80);
      final n2 = Node.withUri(Uri(scheme: 'http', host: host, port: 80));

      expect(n1.path, isEmpty);
      expect(n2.path, isEmpty);
    });
    test('with empty host throws', () {
      expect(
        () => Node(Protocol.http, '', port: 80, path: path),
        throwsA(
          isA<MissingConfiguration>().having(
            (e) => e.message,
            'message',
            'Ensure that Node.host is not empty',
          ),
        ),
      );
      expect(
        () => Node.withUri(Uri(scheme: 'http', host: '', port: 80, path: path)),
        throwsA(
          isA<MissingConfiguration>().having(
            (e) => e.message,
            'message',
            'Ensure that Node.host is not empty',
          ),
        ),
      );
    });
  });
}

import 'dart:async';
import 'dart:convert';

import 'package:test/test.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';

import 'package:typesense/src/services/collections_api_call.dart';
import 'package:typesense/src/services/node_pool.dart';
import 'package:typesense/src/exceptions/exceptions.dart';

import '../test_utils.dart';

void main() {
  group('CollectionsApiCall', () {
    const schemas = [
      {
        "num_documents": 1250,
        "name": "companies",
        "fields": [
          {"name": "company_name", "type": "string"},
          {"name": "num_employees", "type": "int32"},
          {"name": "country", "type": "string", "facet": true}
        ],
        "default_sorting_field": "num_employees"
      },
      {
        "num_documents": 1250,
        "name": "ceos",
        "fields": [
          {"name": "company_name", "type": "string"},
          {"name": "full_name", "type": "string"},
          {"name": "from_year", "type": "int32"}
        ],
        "default_sorting_field": "from_year"
      }
    ];
    test('has a contentType constant', () {
      expect(contentType, equals('Content-Type'));
    });
    test('has a defaultHeaders field', () {
      final config = ConfigurationFactory.withNearestNode(),
          nodePool = NodePool(config),
          collectionsApiCall = CollectionsApiCall(config, nodePool);
      expect(collectionsApiCall.defaultHeaders,
          equals({apiKeyLabel: apiKey, contentType: 'application/json'}));
    });
    test('has a defaultQueryParameters field', () {
      final config = ConfigurationFactory.withNearestNode(
              sendApiKeyAsQueryParam: true),
          nodePool = NodePool(config),
          collectionsApiCall = CollectionsApiCall(config, nodePool);
      expect(collectionsApiCall.defaultQueryParameters,
          equals({apiKeyLabel: apiKey}));
    });
    test('has a get method', () async {
      final client = MockClient(
            (request) async {
              expect(
                  request.url.toString(),
                  equals(
                      'http://$host:$mockServerPort$pathToService/collections?'));
              expect(request.method, equals('GET'));
              expect(request.headers[apiKeyLabel], equals(apiKey));

              return http.Response(json.encode(schemas), 200, request: request);
            },
          ),
          config = ConfigurationFactory.withoutNearestNode(mockClient: client),
          nodePool = NodePool(config);

      expect(
          await CollectionsApiCall(config, nodePool).get(
            '/collections',
          ),
          equals(schemas));
    });
    test('has a send method', () async {
      final client = MockClient(
            (request) async {
              return http.Response(json.encode(schemas), 200, request: request);
            },
          ),
          config = ConfigurationFactory.withNearestNode(mockClient: client),
          nodePool = NodePool(config),
          collectionsApiCall = CollectionsApiCall(config, nodePool);

      expect(
          await collectionsApiCall.send((node) => node.client!.get(
                Uri.http("example.org", "/path"),
              )),
          equals(schemas));
    });
    test('has a decode method', () {
      final config = ConfigurationFactory.withNearestNode(),
          nodePool = NodePool(config),
          collectionsApiCall = CollectionsApiCall(config, nodePool);

      expect(collectionsApiCall.decode(json.encode(schemas)), equals(schemas));
    });
    test('has a requestUri method', () {
      final config = ConfigurationFactory.withNearestNode(),
          nodePool = NodePool(config);
      expect(
          CollectionsApiCall(config, nodePool).getRequestUri(
              NearestNode, '/endpoint',
              queryParams: {'howCool': 'isThat'}).toString(),
          equals(
              'http://$host:$nearestServerPort$pathToService/endpoint?howCool=isThat'));
    });
  });

  group('CollectionsApiCall', () {
    setUp(() async {});
    test('sends api key in the header or query according to the configuration',
        () async {
      var sendApiKeyAsQueryParam = false;
      final client = MockClient(
        (request) async {
          expect(request.url.path, equals('$pathToService/api/key/test'));

          if (sendApiKeyAsQueryParam) {
            expect(request.url.queryParameters[apiKeyLabel], equals(apiKey));
          } else {
            expect(request.headers[apiKeyLabel], equals(apiKey));
          }
          return http.Response('', 200, request: request);
        },
      );

      // Defaults to sending api key in the header
      var config = ConfigurationFactory.withoutNearestNode(
            sendApiKeyAsQueryParam: sendApiKeyAsQueryParam,
            mockClient: client,
          ),
          nodePool = NodePool(config);
      await CollectionsApiCall(config, nodePool).get('/api/key/test');

      // Sending api key as query parameter now
      sendApiKeyAsQueryParam = true;
      config = ConfigurationFactory.withoutNearestNode(
        sendApiKeyAsQueryParam: sendApiKeyAsQueryParam,
        mockClient: client,
      );
      nodePool = NodePool(config);
      await CollectionsApiCall(config, nodePool).get('/api/key/test');
    });
    test(
        'sets the health status of a node according to completion of the request',
        () async {
      var requestNumber = 0;
      final client = MockClient(
            (request) async {
              expect(request.url.path,
                  equals('$pathToService/health/status/test'));
              switch (++requestNumber) {
                case 1:
                  return http.Response('', 500, request: request);
                case 2:
                  return http.Response('', 0, request: request);
                default:
                  return http.Response('', 200, request: request);
              }
            },
          ),
          node1 = NearestNode.copyWith(client: client),
          node2 = MockNode.copyWith(client: client),
          node3 = UnavailableNode.copyWith(client: client),
          config = ConfigurationFactory.withoutNearestNode(
            nodes: {node1, node2, node3},
            retryInterval: Duration.zero,
          ),
          nodePool = NodePool(config);

      expect(node1.isHealthy, isTrue);
      expect(node2.isHealthy, isTrue);
      expect(node3.isHealthy, isTrue);

      final now = DateTime.now();
      await CollectionsApiCall(config, nodePool).get('/health/status/test');

      expect(node1.isHealthy, isFalse); // returned 500 status
      expect(node1.lastAccessTimestamp.compareTo(now) > 0, isTrue);
      expect(node2.isHealthy, isFalse); // returned 0 status
      expect(node2.lastAccessTimestamp.compareTo(now) > 0, isTrue);
      expect(node3.isHealthy, isTrue);
      expect(node3.lastAccessTimestamp.compareTo(now) > 0, isTrue);
    });
    test('retries a request after Configuration.retryInterval duration',
        () async {
      DateTime? firstRequestTime, secondRequestTime;
      final retryInterval = Duration(milliseconds: 900),
          client = MockClient(
            (request) async {
              expect(request.url.path,
                  equals('$pathToService/retry/interval/test'));
              if (firstRequestTime == null) {
                firstRequestTime = DateTime.now();
                return http.Response('', 500, request: request);
              } else {
                secondRequestTime = DateTime.now();
                return http.Response('', 200, request: request);
              }
            },
          ),
          config = ConfigurationFactory.withoutNearestNode(
              mockClient: client, retryInterval: retryInterval),
          nodePool = NodePool(config);

      await CollectionsApiCall(config, nodePool).get('/retry/interval/test');
      // Atleast [retryInterval] delay between requests.
      expect(secondRequestTime!.difference(firstRequestTime!) > retryInterval,
          isTrue);
    });
    test(
      'retries a request Configuration.numRetries times if an exception occurs',
      () async {
        var numTries = 0;
        final client = MockClient(
              (request) async {
                expect(request.url.path, equals('$pathToService/retries/test'));
                numTries++;
                return http.Response('', 500, request: request);
              },
            ),
            config = ConfigurationFactory.withoutNearestNode(
              mockClient: client,
              numRetries: 5,
            ),
            nodePool = NodePool(config);

        try {
          await CollectionsApiCall(config, nodePool).get('/retries/test');
        } catch (e) {
          // Exception is rethrown when Configuration.numRetries run out
          expect(e, isA<ServerError>());
          expect(numTries, equals(5));
        }
      },
    );
  });

  group('CollectionsApiCall throws', () {
    test(
        'TimeoutException when no response is received for Configuration.connectionTimeout duration',
        () {
      final client = MockClient(
            (request) async {
              expect(request.url.path, equals('$pathToService/timeout/test'));

              return await Future.delayed(
                      Duration(seconds: 1, milliseconds: 10))
                  .then((_) => http.Response('', 200, request: request));
            },
          ),
          config = ConfigurationFactory.withoutNearestNode(mockClient: client),
          nodePool = NodePool(config);

      expect(
        () async {
          await CollectionsApiCall(config, nodePool).get('/timeout/test');
        },
        throwsA(isA<TimeoutException>().having(
          (e) => e.duration,
          'duration',
          equals(Duration(seconds: 1)),
        )),
      );
    });
    test(
      'immediately for Http response code < 500',
      () async {
